const router = Router();
router.use(idempotency());
const tenant = (req: Request) => String(req.auth?.tenantId ?? req.header('x-tenant-id') ?? '000000000000000000000001');
const envelope = (data: any, req: Request) => ({ success: true, data, meta: { requestId: req.requestId } });
const userView = (u: any) => { const value = u.toObject ? u.toObject() : { ...u }; delete value.passwordHash; return value; };
const paged = (req: Request, data: any[], fingerprint: string) => { const limit = pageLimit(req.query.limit); const hasMore = data.length > limit; const items = hasMore ? data.slice(0, limit) : data; const last = items.at(-1); return { success: true, data: items, meta: { requestId: req.requestId, pagination: { nextCursor: hasMore && last ? encodeCursor({ updatedAt: new Date(last.updatedAt ?? last.timestamp ?? 0).toISOString(), id: String(last._id), fingerprint }) : null, hasMore, limit } } }; };

router.post('/auth/login', validate(z.object({ body: z.object({ email: z.string().email(), password: z.string().min(8) }), params: z.any(), query: z.any() })), async (req, res, next) => { try { const result = await signIn(req.body.email, req.body.password, tenant(req), { ip: req.ip, userAgent: req.get('user-agent'), requestId: req.requestId }); res.cookie('refresh_token', `${result.sessionId}.${result.refreshToken}`, { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'lax', maxAge: 30 * 86400000 }); res.json(envelope({ user: userView(result.user), accessToken: result.accessToken, sessionId: result.sessionId }, req)); } catch (e) { next(e); } });
router.post('/auth/refresh', async (req, res, next) => { try { const value = req.cookies?.refresh_token as string | undefined; if (!value) throw new Error('TOKEN_INVALID'); const [sessionId, token] = value.split('.'); const nextToken = await rotateRefresh(sessionId, token); const raw = await (await import('../config/connections.js')).redis.get(`refresh:${sessionId}`); if (!raw) throw new Error('TOKEN_INVALID'); const record = JSON.parse(raw); const accessToken = await issueAccessToken({ userId: record.userId, tenantId: record.tenantId, sessionId, roleIds: record.roleIds ?? [], authVersion: record.authVersion ?? 1 }); res.cookie('refresh_token', `${sessionId}.${nextToken}`, { httpOnly: true, secure: process.env.NODE_ENV === 'production', sameSite: 'lax', maxAge: 30 * 86400000 }); res.json(envelope({ accessToken, sessionId, rotated: true }, req)); } catch (e) { next(e); } });
router.get('/auth/sessions', requireAuth, async (req, res, next) => { try { res.json(envelope(await listSessions(req.auth!.userId, tenant(req)), req)); } catch (e) { next(e); } });
router.delete('/auth/sessions/:id', requireAuth, async (req, res, next) => { try { await revokeSession(String(req.params.id), req.auth!.userId, tenant(req)); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'auth.session_revoked', entity: { type: 'session', id: String(req.params.id) }, requestId: req.requestId, result: 'success' }); res.status(204).end(); } catch (e) { next(e); } });
router.post('/auth/logout', requireAuth, async (req, res, next) => { try { const value = req.cookies?.refresh_token as string | undefined; if (value) { const [sessionId] = value.split('.'); const { redis } = await import('../config/connections.js'); await redis.del(`refresh:${sessionId}`); } res.clearCookie('refresh_token'); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'auth.logout', entity: { type: 'user', id: req.auth!.userId }, result: 'success', requestId: req.requestId }); res.status(204).end(); } catch (e) { next(e); } });
router.get('/auth/me', requireAuth, async (req, res, next) => { try { const user = await User.findOne({ _id: asId(req.auth!.userId), tenantId: tenant(req) }).populate({ path: 'roleIds', populate: { path: 'permissionIds' } }); if (!user) throw Object.assign(new Error('RESOURCE_NOT_FOUND'), { status: 404 }); res.json(envelope({ user: userView(user), roles: user.roleIds, permissions: req.auth!.permissions }, req)); } catch (e) { next(e); } });

router.post('/auth/register', requireAuth, requirePermission('user:create'), validate(z.object({ body: z.object({ email: z.string().email(), password: z.string().min(8), firstName: z.string().min(1), lastName: z.string().min(1), roleIds: z.array(z.string()).optional(), departmentId: z.string().optional(), businessUnitIds: z.array(z.string()).optional() }), params: z.any(), query: z.any() })), async (req, res, next) => { try { const t = tenant(req); const user = await User.create({ tenantId: t, email: req.body.email, normalizedEmail: req.body.email.toLowerCase(), passwordHash: await hashPassword(req.body.password), profile: { firstName: req.body.firstName, lastName: req.body.lastName, displayName: `${req.body.firstName} ${req.body.lastName}` }, organization: { departmentId: req.body.departmentId, businessUnitIds: req.body.businessUnitIds }, roleIds: (req.body.roleIds ?? []).map(asId), status: 'active' }); await writeAudit({ tenantId: t, actorId: req.auth!.userId, action: 'user.created', entity: { type: 'user', id: user.id }, result: 'success', requestId: req.requestId }); res.status(201).json(envelope(userView(user), req)); } catch (e) { next(e); } });

router.get('/users', requireAuth, requirePermission('user:read'), async (req, res, next) => { try { const filter: any = { tenantId: tenant(req) }; if (req.query.status) filter.status = req.query.status; if (req.query.q) filter.$or = [{ normalizedEmail: new RegExp(String(req.query.q).toLowerCase(), 'i') }, { 'profile.displayName': new RegExp(String(req.query.q), 'i') }]; const data = await User.find(filter).select('-passwordHash').sort({ updatedAt: -1, _id: -1 }).limit(Math.min(Number(req.query.limit) || 25, 100)); res.json(envelope(data.map(userView), req)); } catch (e) { next(e); } });
router.get('/users/:id', requireAuth, requirePermission('user:read'), async (req, res, next) => { try { const user = await User.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }).select('-passwordHash'); if (!user) return res.status(404).json({ success: false, error: { code: 'USER_NOT_FOUND', message: 'User not found' } }); res.json(envelope(userView(user), req)); } catch (e) { next(e); } });
router.patch('/users/:id', requireAuth, requirePermission('user:update'), async (req, res, next) => { try { const allowed = ['profile', 'organization', 'roleIds', 'status']; const update: any = {}; for (const key of allowed) if (req.body[key] !== undefined) update[key] = key === 'roleIds' ? req.body[key].map(asId) : req.body[key]; update.updatedAt = new Date(); const user = await User.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req) }, { $set: update, $inc: { authVersion: update.status ? 1 : 0 } }, { new: true }).select('-passwordHash'); if (!user) return res.status(404).json({ success: false, error: { code: 'USER_NOT_FOUND', message: 'User not found' } }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'user.updated', entity: { type: 'user', id: user.id }, newValue: update, result: 'success', requestId: req.requestId }); res.json(envelope(userView(user), req)); } catch (e) { next(e); } });
router.delete('/users/:id', requireAuth, requirePermission('user:manage'), async (req, res, next) => { try { const user = await User.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req) }, { $set: { status: 'deactivated', updatedAt: new Date() }, $inc: { authVersion: 1 } }, { new: true }); if (!user) return res.status(404).end(); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'user.deactivated', entity: { type: 'user', id: user.id }, result: 'success' }); res.status(204).end(); } catch (e) { next(e); } });

router.get('/roles', requireAuth, requirePermission('role:read'), async (req, res, next) => { try { res.json(envelope(await Role.find({ tenantId: tenant(req), status: req.query.status ?? 'active' }).populate('permissionIds'), req)); } catch (e) { next(e); } });
router.post('/roles', requireAuth, requirePermission('role:create'), async (req, res, next) => { try { const role = await Role.create({ tenantId: tenant(req), name: req.body.name, key: req.body.key, permissionIds: (req.body.permissionIds ?? []).map(asId), scopeRules: req.body.scopeRules, status: 'active' }); res.status(201).json(envelope(role, req)); } catch (e) { next(e); } });
router.patch('/roles/:id', requireAuth, requirePermission('role:update'), async (req, res, next) => { try { const update: any = { ...req.body, updatedAt: new Date() }; if (update.permissionIds) update.permissionIds = update.permissionIds.map(asId); const role = await Role.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req) }, { $set: update }, { new: true }); if (!role) return res.status(404).end(); res.json(envelope(role, req)); } catch (e) { next(e); } });
router.get('/permissions', requireAuth, requirePermission('permission:read'), async (req, res, next) => { try { res.json(envelope(await Permission.find({ status: req.query.status ?? 'active' }), req)); } catch (e) { next(e); } });

router.get('/contracts', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { if (req.query.q) return res.json(envelope(await searchProvider.search({ tenantId: tenant(req), q: String(req.query.q), limit: pageLimit(req.query.limit) }), req)); const filter: any = { tenantId: tenant(req) }; for (const field of ['status', 'contractType', 'ownerId', 'departmentId', 'businessUnitId']) if (req.query[field]) filter[field] = req.query[field]; const fingerprint = queryFingerprint({ tenant: tenant(req), filter, sort: 'updatedAt:-1,_id:-1' }); const cursor = decodeCursor(req.query.cursor); if (cursor && cursor.fingerprint !== fingerprint) throw new Error('INVALID_CURSOR'); if (cursor) filter.$or = [{ updatedAt: { $lt: new Date(cursor.updatedAt) } }, { updatedAt: new Date(cursor.updatedAt), _id: { $lt: asId(cursor.id) } }]; const data = await Contract.find(filter).sort({ updatedAt: -1, _id: -1 }).limit(pageLimit(req.query.limit) + 1); res.json(paged(req, data, fingerprint)); } catch (e) { next(e); } });
router.post('/contracts', requireAuth, requirePermission('contract:create'), validate(contractCreate), async (req, res, next) => { try { const contract = await Contract.create({ ...req.body, tenantId: tenant(req), ownerId: asId(req.body.ownerId ?? req.auth!.userId), status: 'draft' }); const version = await ContractVersion.create({ tenantId: tenant(req), contractId: contract.id, versionNumber: 1, state: 'draft', authorId: req.auth!.userId, changeSummary: 'Initial draft' }); contract.currentVersionId = version.id; await contract.save(); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.created', entity: { type: 'contract', id: contract.id }, newValue: { status: 'draft' }, result: 'success', requestId: req.requestId }); res.status(201).json(envelope(contract, req)); } catch (e) { next(e); } });
router.get('/contracts/:id', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { const c = await Contract.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }); if (!c) return res.status(404).json({ success: false, error: { code: 'CONTRACT_NOT_FOUND', message: 'Contract not found' } }); res.json(envelope(c, req)); } catch (e) { next(e); } });
router.patch('/contracts/:id', requireAuth, requirePermission('contract:update'), async (req, res, next) => { try { const c = await Contract.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }); if (!c) return res.status(404).end(); if (c.status !== 'draft' && c.status !== 'review') throw new Error('CONFLICT'); const expected = Number(req.body.version ?? c.version); if (expected !== c.version) throw new Error('VERSION_CONFLICT'); Object.assign(c, req.body); c.version += 1; await c.save(); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.updated', entity: { type: 'contract', id: c.id }, result: 'success', requestId: req.requestId }); res.json(envelope(c, req)); } catch (e) { next(e); } });
router.delete('/contracts/:id', requireAuth, requirePermission('contract:delete'), async (req, res, next) => { try { const c = await Contract.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req), status: 'draft' }, { $set: { status: 'archived', updatedAt: new Date() } }, { new: true }); if (!c) return res.status(404).json({ success: false, error: { code: 'CONTRACT_NOT_FOUND', message: 'Draft contract not found' } }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.deleted', entity: { type: 'contract', id: c.id }, result: 'success' }); res.status(204).end(); } catch (e) { next(e); } });
router.post('/contracts/:id/submit-review', requireAuth, requirePermission('contract:submit-review'), async (req, res, next) => { try { assertTransition('draft', 'review'); const c = await Contract.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req), status: 'draft', version: Number(req.body.version) }, { $set: { status: 'review', updatedAt: new Date() }, $inc: { version: 1 } }, { new: true }); if (!c) throw new Error('CONFLICT'); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.submitted', entity: { type: 'contract', id: c.id }, result: 'success', requestId: req.requestId }); await publishEvent({ name: 'ContractSubmitted.v1', tenantId: tenant(req), actorId: req.auth!.userId, entityId: c.id, requestId: req.requestId, payload: { contractId: c.id, status: c.status } }); const execution = await executeWorkflow(c.id, req.auth!.userId, req.requestId); res.json(envelope({ contract: execution.contract, workflowId: execution.workflow.id, taskIds: execution.tasks.map((task: any) => task.id) }, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/archive', requireAuth, requirePermission('contract:archive'), async (req, res, next) => { try { const c = await Contract.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req), status: { $in: ['active', 'monitoring', 'renewal'] }, version: Number(req.body.version) }, { $set: { status: 'archived', updatedAt: new Date() }, $inc: { version: 1 } }, { new: true }); if (!c) throw new Error('CONFLICT'); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.archived', entity: { type: 'contract', id: c.id }, result: 'success' }); res.json(envelope(c, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/renew', requireAuth, requirePermission('renewal:create'), validate(renewalRequest), async (req, res, next) => { try { const renewal = await createRenewal(String(req.params.id), tenant(req), req.auth!.userId, req.body.targetExpiryDate ? new Date(req.body.targetExpiryDate) : undefined, req.requestId); res.status(201).json(envelope(renewal, req)); } catch (e) { next(e); } });
router.get('/contracts/:id/history', requireAuth, requirePermission('contract:history'), async (req, res, next) => { try { const events = await AuditLog.find({ tenantId: tenant(req), 'entity.type': 'contract', 'entity.id': String(req.params.id) }).sort({ timestamp: -1 }).limit(Math.min(Number(req.query.limit) || 50, 100)); res.json(envelope(events, req)); } catch (e) { next(e); } });
router.get('/contracts/:id/versions', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { res.json(envelope(await ContractVersion.find({ tenantId: tenant(req), contractId: asId(String(req.params.id)) }).sort({ versionNumber: -1 }), req)); } catch (e) { next(e); } });
router.post('/contracts/:id/versions', requireAuth, requirePermission('contract:update'), async (req, res, next) => { try { const previous = await ContractVersion.findOne({ tenantId: tenant(req), contractId: asId(String(req.params.id)) }).sort({ versionNumber: -1 }); const v = await ContractVersion.create({ tenantId: tenant(req), contractId: asId(String(req.params.id)), versionNumber: (previous?.versionNumber ?? 0) + 1, state: 'draft', authorId: req.auth!.userId, previousVersionId: previous?._id, changeSummary: req.body.changeSummary, contentRef: req.body.contentRef }); res.status(201).json(envelope(v, req)); } catch (e) { next(e); } });
router.get('/contracts/:id/compare', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { const query = z.object({ fromVersionId: z.string().length(24), toVersionId: z.string().length(24) }).parse(req.query); const result = await compareVersions(tenant(req), String(req.params.id), query.fromVersionId, query.toVersionId); res.json(envelope(result, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/redlines', requireAuth, requirePermission('contract:collaborate'), validate(redlineCreate), async (req, res, next) => { try { const result = await createRedline({ tenantId: tenant(req), contractId: String(req.params.id), actorId: req.auth!.userId, baseVersionId: req.body.baseVersionId, expectedContractVersion: req.body.expectedContractVersion, changeSummary: req.body.changeSummary, operations: req.body.operations, requestId: req.requestId }); res.status(201).json(envelope(result, req)); } catch (e) { next(e); } });
router.get('/contracts/:id/comments', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { const filter: any = { tenantId: tenant(req), contractId: asId(String(req.params.id)) }; if (req.query.versionId) filter.contractVersionId = asId(String(req.query.versionId)); if (req.query.status) filter.status = String(req.query.status); const data = await CollaborationComment.find(filter).sort({ createdAt: 1 }); res.json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/comments', requireAuth, requirePermission('contract:comment'), validate(collaborationCommentCreate), async (req, res, next) => { try { const contract = await Contract.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }); const version = contract && await ContractVersion.findOne({ _id: asId(req.body.versionId), contractId: contract._id, tenantId: tenant(req) }); if (!contract || !version) throw new Error('VERSION_NOT_FOUND'); const mentions = req.body.mentions ?? []; if (mentions.length && (await User.countDocuments({ _id: { $in: mentions.map(asId) }, tenantId: tenant(req), status: 'active' })) !== mentions.length) throw new Error('MENTION_SCOPE_INVALID'); const comment = await CollaborationComment.create({ tenantId: tenant(req), contractId: contract._id, contractVersionId: version._id, parentId: req.body.parentId ? asId(req.body.parentId) : undefined, authorId: asId(req.auth!.userId), body: req.body.body, anchor: req.body.anchor, mentions: mentions.map(asId) }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.comment.created', entity: { type: 'collaborationComment', id: comment.id }, metadata: { contractId: contract.id, versionId: version.id }, requestId: req.requestId, result: 'success' }); await publishEvent({ name: 'ContractCommentCreated.v1', tenantId: tenant(req), actorId: req.auth!.userId, entityId: contract.id, requestId: req.requestId, payload: { commentId: comment.id, contractId: contract.id, versionId: version.id } }); await Promise.all(mentions.filter((userId: string) => userId !== req.auth!.userId).map((recipientUserId: string) => createNotification({ tenantId: tenant(req), recipientUserId: asId(recipientUserId), actorId: req.auth!.userId, type: 'contract.comment.mention', category: 'collaboration', title: 'You were mentioned in a contract discussion', message: `${req.body.body.slice(0, 180)}${req.body.body.length > 180 ? '…' : ''}`, entityType: 'contract', entityId: contract.id, requestId: req.requestId }))); res.status(201).json(envelope(comment, req)); } catch (e) { next(e); } });
router.post('/comments/:id/resolve', requireAuth, requirePermission('contract:resolve-comment'), validate(collaborationCommentResolve), async (req, res, next) => { try { const comment = await resolveComment(tenant(req), String(req.params.id), req.auth!.userId, req.body.version, req.requestId); res.json(envelope(comment, req)); } catch (e) { next(e); } });
router.get('/contracts/:id/intelligence', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { const data = await listContractIntelligence(tenant(req), String(req.params.id)); res.json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/intelligence/analyze', requireAuth, requirePermission('contract:update'), async (req, res, next) => { try { const body = z.object({ playbook: z.array(z.string().min(1).max(1000)).max(100).optional() }).strict().parse(req.body); const data = await analyzeContract(tenant(req), String(req.params.id), req.auth!.userId, body.playbook ?? []); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.intelligence.analyzed', entity: { type: 'contract', id: String(req.params.id) }, metadata: { intelligenceId: data.id, provider: data.provider, model: data.model }, requestId: req.requestId, result: 'success' }); res.status(201).json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/intelligence/ask', requireAuth, requirePermission('contract:read'), async (req, res, next) => { try { const body = z.object({ question: z.string().min(3).max(2000), intelligenceId: z.string().optional() }).strict().parse(req.body); const data = await answerContractQuestion(tenant(req), String(req.params.id), req.auth!.userId, body.question, body.intelligenceId); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.intelligence.question_asked', entity: { type: 'contract', id: String(req.params.id) }, metadata: { intelligenceId: data.id }, requestId: req.requestId, result: 'success' }); res.status(201).json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/intelligence/:id/review', requireAuth, requirePermission('contract:update'), async (req, res, next) => { try { const body = z.object({ decision: z.enum(['accepted', 'overridden']), notes: z.string().max(4000).optional() }).strict().parse(req.body); const data = await reviewIntelligence(tenant(req), String(req.params.id), req.auth!.userId, body.decision, body.notes); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'contract.intelligence.reviewed', entity: { type: 'contractIntelligence', id: data.id }, metadata: { decision: body.decision }, requestId: req.requestId, result: 'success' }); res.json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/contracts/:id/signature/request', requireAuth, requirePermission('signature:request'), validate(signatureRequest), async (req, res, next) => { try { const result = await requestSignature(String(req.params.id), tenant(req), req.auth!.userId, req.body.provider, req.body.signers, req.body.contractVersionId, new Date(req.body.expiresAt), req.requestId); res.status(201).json(envelope(result, req)); } catch (e) { next(e); } });
