router.post('/documents/:id/finalize', requireAuth, requirePermission('document:upload'), validate(documentFinalize), async (req, res, next) => { try { const doc: any = await Document.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }).select('+storageKey'); if (!doc) throw new Error('DOCUMENT_NOT_FOUND'); const verified = await storageProvider.verifyUpload(doc.storageKey); if (!verified.exists || verified.checksum !== req.body.checksum || req.body.checksum !== doc.checksum) throw new Error('DOCUMENT_CHECKSUM_MISMATCH'); const scan = await documentScanner.scan({ fileName: doc.fileName, mimeType: doc.mimeType, checksum: doc.checksum }); doc.uploadStatus = scan.status === 'infected' ? 'quarantined' : 'uploaded'; doc.scanStatus = scan.status; doc.scanMetadata = { signature: scan.signature, scannedAt: new Date() }; doc.version += 1; await doc.save(); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'document.uploaded', entity: { type: 'document', id: doc.id }, requestId: req.requestId, result: 'success' }); await publishEvent({ name: 'DocumentUploaded.v1', tenantId: tenant(req), actorId: req.auth!.userId, entityId: doc.id, requestId: req.requestId, payload: { documentId: doc.id, contractId: String(doc.contractId), scanStatus: doc.scanStatus } }); await publishEvent({ name: 'DocumentScanCompleted.v1', tenantId: tenant(req), actorId: req.auth!.userId, entityId: doc.id, requestId: req.requestId, payload: { documentId: doc.id, scanStatus: doc.scanStatus } }); res.json(envelope({ documentId: doc.id, uploadStatus: doc.uploadStatus, scanStatus: doc.scanStatus }, req)); } catch (e) { next(e); } });
