router.post('/approvals/:id/delegate', requireAuth, requirePermission('approval:delegate'), validate(approvalAction), async (req, res, next) => { try { if (!req.body.delegateToUserId || !req.body.reason || !req.body.expiresAt || new Date(req.body.expiresAt) <= new Date()) return res.status(400).json({ success: false, error: { code: 'DELEGATION_INVALID', message: 'Delegate user, reason, and future expiration date are required' } }); const delegate = await User.findOne({ _id: asId(req.body.delegateToUserId), tenantId: tenant(req), status: 'active' }); if (!delegate) return res.status(400).json({ success: false, error: { code: 'DELEGATE_USER_NOT_FOUND', message: 'Delegate user is not active in this tenant' } }); const task: any = await ApprovalTask.findOneAndUpdate({ _id: asId(String(req.params.id)), tenantId: tenant(req), assignedUserId: asId(req.auth!.userId), status: { $in: ['pending', 'in_progress'] } }, { $set: { assignedUserId: delegate._id, status: 'delegated', comments: req.body.reason, delegation: { delegatedBy: req.auth!.userId, expiresAt: new Date(req.body.expiresAt) } }, $push: { history: { action: 'delegated', actorId: req.auth!.userId, delegateTo: delegate.id, reason: req.body.reason, expiresAt: new Date(req.body.expiresAt), at: new Date() } } }, { new: true }); if (!task) throw new Error('CONFLICT'); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'approval.delegated', entity: { type: 'approvalTask', id: task.id }, metadata: { delegateTo: delegate.id, expiresAt: req.body.expiresAt }, result: 'success' }); res.json(envelope(task, req)); } catch (e) { next(e); } });


router.get('/intake/questionnaires', requireAuth, requirePermission('intake:read'), async (req, res, next) => { try { const filter: any = { tenantId: tenant(req), status: 'published' }; if (req.query.contractType) filter.contractType = String(req.query.contractType); const data = await IntakeQuestionnaire.find(filter).sort({ contractType: 1, version: -1 }).lean(); res.json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/intake/questionnaires', requireAuth, requirePermission('intake:manage'), async (req, res, next) => { try { const body = z.object({ contractType: z.string().min(1).max(100), status: z.enum(['draft', 'published', 'retired']).default('draft'), questions: z.array(z.object({ key: z.string().regex(/^[a-z][a-z0-9_]*$/), label: z.string().min(1).max(200), type: z.enum(['text', 'textarea', 'number', 'date', 'select', 'boolean']), required: z.boolean().default(false), options: z.array(z.string().max(100)).max(50).optional(), visibleWhen: z.unknown().optional() }).strict()).max(100), routingRules: z.array(z.unknown()).max(100).default([]) }).strict().parse(req.body); const latest: any = await IntakeQuestionnaire.findOne({ tenantId: tenant(req), contractType: body.contractType }).sort({ version: -1 }); const questionnaire = await IntakeQuestionnaire.create({ tenantId: tenant(req), contractType: body.contractType, version: (latest?.version ?? 0) + 1, status: body.status, questions: body.questions, routingRules: body.routingRules, ownerId: req.auth!.userId }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'intake.questionnaire.created', entity: { type: 'intakeQuestionnaire', id: questionnaire.id }, metadata: { contractType: body.contractType, version: questionnaire.version }, result: 'success', requestId: req.requestId }); res.status(201).json(envelope(questionnaire, req)); } catch (e) { next(e); } });
router.get('/intake/requests', requireAuth, requirePermission('intake:read'), async (req, res, next) => { try { const filter: any = { tenantId: tenant(req) }; if (req.query.status) filter.status = String(req.query.status); if (req.query.requesterId) filter.requesterId = asId(String(req.query.requesterId)); const data = await IntakeRequest.find(filter).sort({ createdAt: -1, _id: -1 }).limit(Math.min(Number(req.query.limit) || 50, 100)); res.json(envelope(data, req)); } catch (e) { next(e); } });
router.post('/intake/requests', requireAuth, requirePermission('intake:create'), async (req, res, next) => { try { const body = z.object({ title: z.string().min(1).max(240), contractType: z.string().min(1).max(100), questionnaireVersion: z.number().int().positive().optional(), answers: z.record(z.string(), z.unknown()).default({}), attachments: z.array(z.string()).max(20).default([]), priority: z.enum(['low', 'normal', 'high', 'urgent']).default('normal') }).strict().parse(req.body); const questionnaire: any = await IntakeQuestionnaire.findOne({ tenantId: tenant(req), contractType: body.contractType, status: 'published', ...(body.questionnaireVersion ? { version: body.questionnaireVersion } : {}) }).sort({ version: -1 }); if (!questionnaire) throw new Error('INTAKE_QUESTIONNAIRE_NOT_FOUND'); const missing = (questionnaire.questions ?? []).filter((q: any) => q.required && (body.answers[q.key] === undefined || body.answers[q.key] === null || body.answers[q.key] === '')).map((q: any) => q.key); if (missing.length) throw Object.assign(new Error('INTAKE_REQUIRED_ANSWERS_MISSING'), { details: { missing } }); const request = await IntakeRequest.create({ tenantId: tenant(req), requesterId: req.auth!.userId, title: body.title, contractType: body.contractType, questionnaireVersion: questionnaire.version, answers: body.answers, attachments: body.attachments.map(asId), priority: body.priority, status: 'submitted' }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'intake.request.submitted', entity: { type: 'intakeRequest', id: request.id }, metadata: { contractType: body.contractType, priority: body.priority }, result: 'success', requestId: req.requestId }); await publishEvent({ name: 'IntakeRequestSubmitted.v1', tenantId: tenant(req), actorId: req.auth!.userId, entityId: request.id, requestId: req.requestId, payload: { intakeRequestId: request.id, contractType: body.contractType } }); res.status(201).json(envelope(request, req)); } catch (e) { next(e); } });
router.post('/intake/requests/:id/convert', requireAuth, requirePermission('intake:manage'), async (req, res, next) => { try { const request: any = await IntakeRequest.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req), status: { $in: ['submitted', 'triage', 'in_progress'] } }); if (!request) throw new Error('INTAKE_REQUEST_NOT_FOUND'); const contract = await Contract.create({ tenantId: tenant(req), contractNumber: String(req.body.contractNumber ?? `INTAKE-${String(request._id).slice(-8).toUpperCase()}`), title: request.title, contractType: request.contractType, ownerId: request.requesterId, status: 'draft', metadata: { intakeRequestId: request.id, answers: request.answers } }); const version = await ContractVersion.create({ tenantId: tenant(req), contractId: contract.id, versionNumber: 1, state: 'draft', authorId: req.auth!.userId, changeSummary: 'Created from intake request' }); contract.currentVersionId = version.id; await contract.save(); request.status = 'converted'; request.version += 1; request.conversion = { contractId: contract.id, convertedBy: req.auth!.userId, convertedAt: new Date() }; await request.save(); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'intake.request.converted', entity: { type: 'intakeRequest', id: request.id }, metadata: { contractId: contract.id }, result: 'success', requestId: req.requestId }); res.status(201).json(envelope({ request, contract }, req)); } catch (e) { next(e); } });

router.get('/integrations', requireAuth, requirePermission('integration:read'), async (req, res, next) => { try { const data = await Integration.find({ tenantId: tenant(req) }).sort({ updatedAt: -1 }).lean(); res.json(envelope(data.map(redactedIntegration), req)); } catch (e) { next(e); } });
router.post('/integrations', requireAuth, requirePermission('integration:create'), async (req, res, next) => { try { const body = z.object({ type: z.enum(supportedIntegrationTypes), provider: z.string().min(1).max(80), displayName: z.string().min(1).max(160), config: z.record(z.string(), z.unknown()).default({}), secret: z.unknown().optional() }).strict().parse(req.body); const encrypted = body.secret === undefined ? {} : encryptSecret(body.secret); const integration = await Integration.findOneAndUpdate({ tenantId: tenant(req), type: body.type, provider: body.provider }, { $set: { displayName: body.displayName, config: body.config, ...encrypted, status: 'draft', updatedAt: new Date() }, $setOnInsert: { tenantId: tenant(req), type: body.type, provider: body.provider, version: 1 } }, { upsert: true, new: true, setDefaultsOnInsert: true }); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'integration.created', entity: { type: 'integration', id: integration.id }, metadata: { provider: body.provider, type: body.type }, result: 'success', requestId: req.requestId }); res.status(201).json(envelope(redactedIntegration(integration), req)); } catch (e) { next(e); } });
router.patch('/integrations/:id', requireAuth, requirePermission('integration:update'), async (req, res, next) => { try { const body = z.object({ displayName: z.string().min(1).max(160).optional(), config: z.record(z.string(), z.unknown()).optional(), secret: z.unknown().optional(), status: z.enum(['draft', 'connected', 'degraded', 'disabled']).optional(), version: z.number().int().positive() }).strict().parse(req.body); const current: any = await Integration.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }).select('+secretCiphertext +secretIv +secretTag'); if (!current || current.version !== body.version) throw new Error('VERSION_CONFLICT'); const update: any = { updatedAt: new Date(), version: current.version + 1 }; if (body.displayName !== undefined) update.displayName = body.displayName; if (body.config !== undefined) update.config = body.config; if (body.status !== undefined) update.status = body.status; if (body.secret !== undefined) Object.assign(update, encryptSecret(body.secret)); const integration = await Integration.findOneAndUpdate({ _id: current._id, tenantId: tenant(req), version: body.version }, { $set: update }, { new: true }); if (!integration) throw new Error('VERSION_CONFLICT'); await writeAudit({ tenantId: tenant(req), actorId: req.auth!.userId, action: 'integration.updated', entity: { type: 'integration', id: integration.id }, metadata: { status: integration.status }, result: 'success', requestId: req.requestId }); res.json(envelope(redactedIntegration(integration), req)); } catch (e) { next(e); } });
router.post('/integrations/:id/test', requireAuth, requirePermission('integration:update'), async (req, res, next) => { try { const integration: any = await Integration.findOne({ _id: asId(String(req.params.id)), tenantId: tenant(req) }).select('+secretCiphertext +secretIv +secretTag'); if (!integration) throw new Error('RESOURCE_NOT_FOUND'); const secret = integration.secretCiphertext ? decryptSecret(integration) : undefined; const health = providerHealthStatus(integration.type, secret); integration.status = health.status; integration.lastHealthCheckAt = new Date(); integration.lastError = health.status === 'connected' ? undefined : health.message; await integration.save(); res.json(envelope({ ...redactedIntegration(integration), health }, req)); } catch (e) { next(e); } });

router.post('/webhooks/:provider', async (req, res, next) => { try { const provider = String(req.params.provider); if (!supportedIntegrationTypes.includes(provider as any)) throw new Error('UNSUPPORTED_PROVIDER'); const externalEventId = String(req.header('x-event-id') ?? req.body?.event_id ?? req.body?.eventId ?? ''); if (!externalEventId) throw new Error('WEBHOOK_EVENT_ID_REQUIRED'); const rawBody = JSON.stringify(req.body ?? {}); const payloadHash = crypto.createHash('sha256').update(rawBody).digest('hex'); const integration: any = await Integration.findOne({ type: provider, status: { $in: ['connected', 'degraded'] } }).select('+secretCiphertext +secretIv +secretTag').sort({ updatedAt: -1 }); const secret = integration?.secretCiphertext ? decryptSecret(integration) : undefined; const signature = req.header('x-signature') ?? req.header('x-slack-signature') ?? undefined; const timestamp = req.header('x-slack-request-timestamp') ?? undefined; const valid = provider === 'slack' ? Boolean(secret?.signingSecret && verifySlackSignature(rawBody, signature, timestamp, secret.signingSecret)) : Boolean(secret?.webhookSecret && verifyHmacSignature(rawBody, signature, secret.webhookSecret)); if (!valid) return res.status(401).json({ success: false, error: { code: 'WEBHOOK_SIGNATURE_INVALID', message: 'Webhook signature verification failed' } }); const existing = await WebhookEvent.findOne({ tenantId: integration.tenantId, provider, externalEventId }); if (existing) return res.status(200).json({ success: true, data: { received: true, duplicate: true } }); const record = await WebhookEvent.create({ tenantId: integration.tenantId, provider, externalEventId, eventType: String(req.body?.type ?? req.body?.event?.type ?? 'unknown'), signatureValid: true, payloadHash, status: 'received' }); await publishEvent({ name: 'IntegrationWebhookReceived.v1', tenantId: String(integration.tenantId), entityId: record.id, payload: { provider, webhookEventId: record.id, externalEventId } }); res.status(202).json({ success: true, data: { received: true, webhookEventId: record.id } }); } catch (e) { next(e); } });

export default router;
